{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people by providing refreshment settings near chairs and placing entertainment control centrally.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Provides refreshments to a person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup_and_plate_set", "drinkware_arrangement"],
        "required_properties": ["holds_drink", "holds_eatable"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote_control", "tv_controller"],
        "required_properties": ["activates_television"]
      },
      {
        "id": "table",
        "entity_kind": "OBJECT",
        "function": "Supports refreshment settings and entertainment control",
        "required_count": 3,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["coffee_table", "side_table", "desk", "console_table"],
        "required_properties": ["is_flat", "supports_weight"]
      },
      {
        "id": "chair",
        "entity_kind": "OBJECT",
        "function": "Seat for a person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["armchair", "recliner"],
        "required_properties": ["supports_sitting"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Source of visual entertainment",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv_screen", "monitor"],
        "required_properties": ["displays_video"]
      }
    ],
    "functional_relations": [
      {
        "id": "setting_on_table",
        "relation": "on",
        "participant_roles": ["refreshment_setting", "table"]
      ,
      "required": true
      },
      {
        "id": "setting_near_chair",
        "relation": "near",
        "participant_roles": ["refreshment_setting", "chair"]
      ,
      "required": true
      },
      {
        "id": "control_on_table",
        "relation": "on",
        "participant_roles": ["entertainment_control", "table"]
      ,
      "required": true
      },
      {
        "id": "control_accessible_to_chair",
        "relation": "accessible_to",
        "participant_roles": ["entertainment_control", "chair"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshment",
        "operation": "place",
        "participant_roles": ["refreshment_setting", "table"],
        "operation_count": 2
      },
      {
        "id": "place_control",
        "operation": "place",
        "participant_roles": ["entertainment_control", "table"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "cup_and_plate", "visual_description": "Red cup and white plate on the large desk"}
      ],
      "entertainment_control": [
        {"label": "remote", "visual_description": "Black remote control on the large desk"}
      ],
      "table": [
        {"label": "large_desk", "visual_description": "Wooden desk in foreground with items"},
        {"label": "coffee_table", "visual_description": "Low table in center of room"},
        {"label": "side_table", "visual_description": "Small wooden tables next to chairs"},
        {"label": "console_table", "visual_description": "Table under the television"}
      ],
      "chair": [
        {"label": "armchair", "visual_description": "Dark upholstered chair on left"},
        {"label": "armchair", "visual_description": "Dark upholstered chair on right"}
      ],
      "television": [
        {"label": "tv", "visual_description": "Black screen mounted on wall"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_drawers",
        "label": "Desk drawers",
        "visual_description": "Drawers on the large desk",
        "reason": "Closed storage structure that may contain additional refreshment items or the remote control."
      },
      {
        "id": "side_table_shelves",
        "label": "Side table shelves",
        "visual_description": "Open shelving units on the side tables",
        "reason": "Storage compartments that might hold spare cups or plates."
      },
      {
        "id": "coffee_table_underneath",
        "label": "Coffee table storage",
        "visual_description": "Space underneath the coffee table",
        "reason": "Potential storage space for items not currently on top."
      }
    ],
    "inspection_order": [
      "desk_drawers",
      "side_table_shelves",
      "coffee_table_underneath"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
